async function ensureDeviceAccess(){const deviceKey=getDeviceKey(),reauthenticate=new URLSearchParams(location.search).get('device_reauth')==='1';try{const status=await api(`auth/me?deviceKey=${encodeURIComponent(deviceKey)}`);if(status.authenticated)return true;if(status.accessAuthenticated&&!status.revoked){await api('auth/device/enroll',{method:'POST',body:JSON.stringify({deviceKey,label:deviceLabel(),reauthenticate})});if(reauthenticate)history.replaceState(null,'',location.pathname);return true;}if(status.accessAuthenticated&&status.revoked&&reauthenticate){try{await api('auth/device/enroll',{method:'POST',body:JSON.stringify({deviceKey,label:deviceLabel(),reauthenticate:true})});history.replaceState(null,'',location.pathname);return true;}catch(error){renderDeviceGate({revoked:true,message:error.message});return false;}}renderDeviceGate({revoked:status.revoked});return false;}catch(error){renderDeviceGate({message:error.message});return false;}}
