async function load(){state.loading=true;render();try{const [data,calendarData]=await Promise.all([api('dashboard'),api('heydealer').catch(()=>({records:[]}))]);state.unassigned=(data.unassigned||[]).map(mapUnassigned);state.checkedOut=(data.checkedOut||[]).map(mapCheckedOut);state.spots=[...data.spots.map(mapSpot),...state.unassigned];state.calendarRecords=calendarData.records||[];state.backend=true;state.error='';}catch{state.spots=makeInitialSpots();state.unassigned=[];state.checkedOut=[];state.calendarRecords=[];state.backend=false;state.error='운영 데이터베이스가 아직 연결되지 않아 읽기 전용 데모 데이터를 표시합니다.';}finally{state.loading=false;render();}}
