function stats(){const p=state.spots.filter(s=>zones.find(z=>z.id===s.zoneId)?.type==='parking'),parked=p.filter(used).length,activeVehicles=state.spots.filter(s=>used(s)&&!s.isCheckedOut),productization=new Set(activeVehicles.filter(s=>s.isUnassigned||zones.find(z=>z.id===s.zoneId)?.type==='service').map(s=>s.vehicleId||s.id)).size,total=zones.filter(zone=>zone.type==='parking').reduce((sum,zone)=>sum+(parkingLayouts[zone.id]?parkingCapacity(parkingLayouts[zone.id]):Number(zone.count)||0),0),performanceAlerts=activeVehicles.filter(s=>isPerformanceOverdue(s.reperformanceDate||s.performanceDate)),alertVehicles=new Set(attentionVehicles().map(s=>s.vehicleId||s.id));return{total,occupied:parked,productization,empty:Math.max(0,total-parked),alerts:alertVehicles.size,performanceAlerts};}
function visible(){const q=state.query.trim().toLowerCase();return state.spots.filter(s=>{const zone=zones.find(z=>z.id===s.zoneId),inSelectedZone=state.zone==='all'||s.zoneId===state.zone||(state.zone==='productization'&&(s.isUnassigned||zone?.type==='service')),needsCheck=s.alerts.length||isPerformanceOverdue(s.reperformanceDate||s.performanceDate);if(zone?.type==='service'&&!used(s))return false;return inSelectedZone&&(state.filter==='all'||(state.filter==='occupied'&&used(s))||(state.filter==='empty'&&!used(s))||(state.filter==='alert'&&needsCheck)||(state.filter==='service'&&(zone?.type==='service'||s.isUnassigned)))&&(!q||[s.plate,s.model,s.color,s.manager,s.label,s.zone,s.memo].some(v=>String(v).toLowerCase().includes(q)));});}
function highlightSearchZoneTabs(){const query=state.query.trim().toLowerCase(),matchedZones=new Set(query?state.spots.filter(s=>used(s)&&[s.plate,s.model,s.color,s.manager,s.label,s.zone].some(value=>String(value).toLowerCase().includes(query))).map(s=>s.zoneId):[]);document.querySelectorAll('.zone-tabs [data-zone]').forEach(button=>button.classList.toggle('search-match',button.dataset.zone!=='all'&&matchedZones.has(button.dataset.zone)));}
function renderParkingSearchResults(){highlightSearchZoneTabs();const toolbar=document.querySelector('.workspace .toolbar');if(!toolbar)return;toolbar.querySelector('.parking-search-results')?.remove();const query=state.query.trim().toLowerCase();if(!query)return;const searchPool=[...state.spots,...state.checkedOut.filter(vehicle=>!vehicle.currentSpotId)],matches=searchPool.filter(s=>used(s)&&[s.plate,s.model,s.color,s.manager,s.label,s.zone].some(value=>String(value).toLowerCase().includes(query)));const panel=document.createElement('div');panel.className='parking-search-results';panel.setAttribute('aria-live','polite');panel.innerHTML=matches.length?matches.map(s=>{const notes=s.alerts.map(id=>STATUS.find(item=>item.id===id)?.label).filter(Boolean).join(' · ')||'없음',zoneLabel=parkingSearchZoneLabel(s);return`<button type="button" data-search-spot="${esc(s.id)}" aria-label="${esc(s.plate)} 차량 주차 위치로 이동"><strong>${esc(s.plate)}</strong><span>${esc(zoneLabel)||'-'}</span><span>${esc(s.model)||'-'}</span><span>${esc(normalizeVehicleColor(s.color))||'-'}</span><span>${esc(s.manager)||'-'}</span><span>${esc(String(s.checkedInAt||'').slice(0,10))||'-'}</span><span>${esc(notes)}</span></button>`;}).join(''):'<p>일치하는 차량이 없습니다.</p>';toolbar.append(panel);panel.querySelectorAll('[data-search-spot]').forEach(button=>button.onclick=()=>{const vehicle=searchPool.find(item=>item.id===button.dataset.searchSpot);if(!vehicle)return;state.query=vehicle.plate;state.zone='all';state.selected=null;render();requestAnimationFrame(()=>{const cell=[...document.querySelectorAll('.parking-cell[data-spot]')].find(item=>item.dataset.spot===vehicle.id),target=cell||document.querySelector(`.parking-map[data-map-zone="${vehicle.zoneId}"]`);if(!target)return;if(cell)cell.classList.add('search-target');target.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});});});}
function attentionVehicles(){return state.spots.filter(s=>used(s)&&((!s.isCheckedOut&&(s.alerts.length||isPerformanceOverdue(s.reperformanceDate||s.performanceDate)))||(s.isCheckedOut&&!s.isUnassigned&&s.alerts.length))).map(s=>{const reasons=[];if(!s.isCheckedOut&&isPerformanceOverdue(s.reperformanceDate||s.performanceDate))reasons.push('재성능');if(s.alerts.length)reasons.push(...s.alerts.map(id=>STATUS.find(item=>item.id===id)?.label).filter(Boolean));return{...s,reasons};});}
