function attentionDetails(){const vehicles=attentionVehicles();return`${vehicles.slice(0,8).map(vehicle=>`<span>${esc(String(vehicle.plate).slice(-4))}(${vehicle.reasons.map(shortAttentionReason).join('·')})</span>`).join('')}${vehicles.length>=9?'<button type="button" data-attention-more>더보기&gt;</button>':''}${vehicles.length>=4?'<button type="button" class="attention-more-mobile" data-attention-more>더보기&gt;</button>':''}`;}
function showAttentionList(){const vehicles=attentionVehicles(),backdrop=document.createElement('div');backdrop.className='modal-backdrop attention-list-backdrop';backdrop.innerHTML=`<section class="modal attention-list-modal" role="dialog" aria-modal="true" aria-labelledby="attention-list-title"><button class="modal-close" type="button" data-attention-close aria-label="확인 필요 목록 닫기">×</button><h2 id="attention-list-title">확인 필요 차량</h2><p class="attention-list-count">총 ${vehicles.length}대</p><div class="attention-vehicle-list">${vehicles.map(vehicle=>{const warningIcons=vehicle.alerts.map(id=>STATUS.find(status=>status.id===id)).filter(Boolean);return`<article><strong>${esc(vehicle.plate)}</strong><span>${esc(vehicle.model||'차종 미입력')}</span><small>${vehicle.reasons.map(esc).join(' · ')}</small>${warningIcons.length?`<div class="attention-list-icons">${warningIcons.map(status=>`<img src="/${esc(status.icon.normalize('NFD'))}" alt="${esc(status.label)}">`).join('')}</div>`:''}</article>`;}).join('')}</div></section>`;document.body.append(backdrop);const close=()=>backdrop.remove();backdrop.querySelector('[data-attention-close]').onclick=close;backdrop.addEventListener('click',event=>{if(event.target===backdrop)close();});}
