function zoneCard(z,list,renderNow=false){if(!renderNow)return'';const all=state.spots.filter(s=>s.zoneId===z.id),n=all.filter(used).length,shown=z.type==='service'?list.filter(used):list;if(!shown.length)return'';return`<article class="zone-card ${z.type}"><div class="zone-title"><div><span>${z.short}</span><div><h3>${z.name}</h3><small>${z.type==='service'?'서비스 구역':'일반 주차 구역'}</small></div></div><p>${z.type==='service'?`<b>${n}</b>대`:`<b>${n}</b> / ${all.length}대`}</p></div><div class="spot-grid">${shown.map(spot).join('')}</div></article>`;}
let suppressSpotClickUntil=0;
async function dropVehicleOnSpot(sourceId,targetId){if(sourceId===targetId||!requireBackend())return;const source=state.spots.find(spot=>spot.id===sourceId),target=state.spots.find(spot=>spot.id===targetId);if(!source?.vehicleId||!target)return;state.saving=true;try{if(target.vehicleId)await api(`vehicles/${source.vehicleId}/swap`,{method:'POST',body:JSON.stringify({spotId:target.id,sourceVersion:source.vehicleVersion,targetVersion:target.vehicleVersion,spotVersion:target.version})});else await api(`vehicles/${source.vehicleId}/move`,{method:'POST',body:JSON.stringify({spotId:target.id,version:source.vehicleVersion})});const towerChanged=source.zoneId==='tower'||target.zoneId==='tower';await refresh(target.vehicleId?`${source.plate} 차량과 ${target.plate} 차량의 위치를 교환했습니다.`:`${source.plate} 차량을 ${target.zone} ${target.label}(으)로 이동했습니다.`);if(towerChanged)showTowerPassReminder();}catch(error){state.saving=false;state.error=error.message;render();}}
function bindParkingDragAndDrop(container){let sourceId='',touchSource='',touchActive=false,touchTimer=null,dropTarget=null;const clearTargets=()=>{container.querySelectorAll('.is-drag-target').forEach(cell=>cell.classList.remove('is-drag-target'));dropTarget=null;};container.addEventListener('dragstart',event=>{const cell=event.target.closest('[data-spot][draggable=true]');if(!cell)return;sourceId=cell.dataset.spot;cell.classList.add('is-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',sourceId);});container.addEventListener('dragover',event=>{const cell=event.target.closest('[data-spot]');if(!cell||cell.dataset.spot===sourceId)return;event.preventDefault();clearTargets();cell.classList.add('is-drag-target');dropTarget=cell;});container.addEventListener('drop',event=>{event.preventDefault();const targetId=event.target.closest('[data-spot]')?.dataset.spot,id=event.dataTransfer.getData('text/plain')||sourceId;clearTargets();suppressSpotClickUntil=Date.now()+500;if(id&&targetId)dropVehicleOnSpot(id,targetId);});container.addEventListener('dragend',()=>{container.querySelector('.is-dragging')?.classList.remove('is-dragging');clearTargets();sourceId='';});container.addEventListener('touchstart',event=>{const cell=event.target.closest('[data-spot][draggable=true]');if(!cell||event.touches.length!==1)return;touchSource=cell.dataset.spot;touchTimer=setTimeout(()=>{touchActive=true;cell.classList.add('is-dragging');},350);},{passive:true});container.addEventListener('touchmove',event=>{if(!touchSource)return;if(!touchActive){clearTimeout(touchTimer);touchSource='';return;}event.preventDefault();const touch=event.touches[0],cell=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('[data-spot]');clearTargets();if(cell&&cell.dataset.spot!==touchSource){cell.classList.add('is-drag-target');dropTarget=cell;}},{passive:false});container.addEventListener('touchend',()=>{clearTimeout(touchTimer);container.querySelector('.is-dragging')?.classList.remove('is-dragging');if(touchActive&&dropTarget){const targetId=dropTarget.dataset.spot;clearTargets();suppressSpotClickUntil=Date.now()+500;dropVehicleOnSpot(touchSource,targetId);}else clearTargets();touchSource='';touchActive=false;},{passive:true});}
function renderParkingWorkspace(){const tabs=document.querySelector('.zone-tabs'),container=document.querySelector('.zones'),legend=document.querySelector('.legend'),parkingZones=zones.filter(zone=>zone.type!=='service'),serviceZones=zones.filter(zone=>zone.type==='service'),selectedZone=parkingZones.find(item=>item.id===state.zone),productVehicles=state.spots.filter(spot=>used(spot)&&(spot.isUnassigned||serviceZones.some(zone=>zone.id===spot.zoneId)));if(!tabs||!container)return;tabs.innerHTML=`<button data-zone="all" class="${state.zone==='all'?'active':''}">전체</button>`+parkingZones.map(item=>`<button data-zone="${item.id}" class="${state.zone===item.id?'active':''}">${item.short}</button>`).join('')+`<button data-zone="productization" class="${state.zone==='productization'?'active':''}">상품화 (${productVehicles.length})</button>`;tabs.querySelectorAll('[data-zone]').forEach(button=>button.onclick=()=>{state.zone=button.dataset.zone;render();});if(legend)legend.innerHTML=`<strong>상품화 :</strong>${productVehicles.length?productVehicles.map(vehicle=>`<span>${esc(String(vehicle.plate).slice(-4))}</span>`).join(''):'<span>차량 없음</span>'}`;const matches=new Set(visible().map(spot=>spot.id)),renderZone=zone=>{const all=state.spots.filter(spot=>spot.zoneId===zone.id);return parkingLayouts[zone.id]?renderParkingMap(parkingLayouts[zone.id],all,matches,{zoneId:zone.id,expanded:state.expandedLayouts.has(zone.id)}):zoneCard(zone,all.filter(spot=>matches.has(spot.id)),true);},renderProductization=()=>{const serviceCards=serviceZones.map(renderZone).filter(Boolean).join(''),unassigned=state.unassigned.filter(spot=>matches.has(spot.id));return serviceCards+(unassigned.length?`<article class="zone-card service product-unassigned"><div class="zone-title"><div><span>상품화</span><div><h3>주차구역 미배정</h3></div></div><p><b>${unassigned.length}</b>대</p></div><div class="spot-grid">${unassigned.map(spot).join('')}</div></article>`:'');},overviewOrder=['pillar11','b3','roof','tower','b5','auto13'],overviewZones=[...parkingZones].sort((a,b)=>overviewOrder.indexOf(a.id)-overviewOrder.indexOf(b.id));container.classList.toggle('is-all',state.zone==='all');container.innerHTML=state.zone==='all'?overviewZones.map(renderZone).filter(Boolean).join('')+renderProductization():state.zone==='productization'?renderProductization()||'<div class="no-result"><strong>상품화 차량이 없습니다.</strong></div>':renderZone(selectedZone||parkingZones[0])||'<div class="no-result"><strong>현재 구역에 차량이 없습니다.</strong></div>';container.querySelectorAll('[data-toggle-map]').forEach(button=>button.onclick=()=>{const zoneId=button.dataset.toggleMap;if(state.expandedLayouts.has(zoneId))state.expandedLayouts.delete(zoneId);else state.expandedLayouts.add(zoneId);renderParkingWorkspace();});container.querySelectorAll('.parking-map-grid').forEach(grid=>grid.addEventListener('click',event=>{if(Date.now()<suppressSpotClickUntil)return;const cell=event.target.closest('[data-spot]');if(!cell)return;state.selected=cell.dataset.spot;const selected=state.spots.find(spot=>spot.id===state.selected);state.mode=used(selected)?'productization':'assign';render();}));container.querySelectorAll('.zone-card [data-spot]').forEach(cell=>cell.onclick=()=>{if(Date.now()<suppressSpotClickUntil)return;state.selected=cell.dataset.spot;const selected=state.spots.find(spot=>spot.id===state.selected);state.mode=used(selected)?'productization':'assign';render();});bindParkingDragAndDrop(container);alignPinnedMobileParkingMaps();}
function alignPinnedMobileParkingMaps(){if(state.loading||!matchMedia('(max-width: 800px)').matches)return;['pillar11'].forEach(zoneId=>{const scroll=document.querySelector(`.parking-map[data-map-zone="${zoneId}"] .parking-map-scroll`);if(!scroll)return;requestAnimationFrame(()=>{if(scroll.isConnected)scroll.scrollLeft=Math.max(0,scroll.scrollWidth-scroll.clientWidth);});});}
function renderCheckedOutSummary(){const legend=document.querySelector('.legend');if(!legend)return;document.querySelector('.checked-out-summary')?.remove();const parked=state.spots.filter(spot=>used(spot)&&spot.isCheckedOut&&!spot.isUnassigned),row=document.createElement('div');row.className='checked-out-summary';row.innerHTML=`<strong>출고됨 :</strong>${parked.length?parked.map(vehicle=>`<span>${esc(String(vehicle.plate).slice(-4))}</span>`).join(''):'<span>차량 없음</span>'}`;legend.insertAdjacentElement('afterend',row);}
const MANAGERS=['대표님','황정웅대리','권용민주임','김지민대리'];
function managerOptions(current=''){return`<option value="">담당자 선택</option>${MANAGERS.map(name=>`<option value="${name}" ${current===name?'selected':''}>${name}</option>`).join('')}${current&&!MANAGERS.includes(current)?`<option value="${esc(current)}" selected>${esc(current)}</option>`:''}`;}
const VEHICLE_COLORS=['검정','흰색','쥐색','녹색','빨강','파랑','블루','베이지','노랑'];
const colorSelect=value=>`<select name="color" required><option value="">색상을 선택하세요</option>${VEHICLE_COLORS.map(color=>`<option value="${color}" ${normalizeVehicleColor(value)===color?'selected':''}>${color}</option>`).join('')}</select>`;
const heydealerVehicleOptions=()=>{const importedPlates=new Set(boardVehicles().map(vehicle=>String(vehicle.plate||'').replace(/\s/g,''))),records=state.heydealerRecords.filter(record=>!importedPlates.has(String(record.plate||'').replace(/\s/g,'')));return`<option value="">차량 불러오기</option><option value="manual">직접입력</option>${records.map(record=>`<option value="${esc(record.id)}">${esc(record.plate)} · ${esc(record.model)} · ${esc(record.manager)}</option>`).join('')}`;}
function vehicleForm(s){const fresh=!used(s),required=fresh?'required':'',mark=fresh?'<small class="required-mark">(필수)</small>':'',today=new Date().toLocaleDateString('en-CA'),checkedInDate=String(s.checkedInAt||today).slice(0,10);return`<form id="vehicle-form" novalidate>${fresh?`<label class="heydealer-vehicle-picker"><span class="field-title">차량목록</span><select name="heydealerRecord" data-heydealer-vehicle>${heydealerVehicleOptions()}</select></label>`:''}<fieldset class="checkin-fields" ${fresh?'disabled':''}><label><span class="field-title">차량번호${mark}</span><input name="plate" value="${esc(s.plate)}" placeholder="123가 4567" required autocomplete="off"></label><label><span class="field-title">입고일${mark}</span><input type="date" name="checkedInDate" value="${esc(checkedInDate)}" required></label><div class="form-row"><label><span class="field-title">차명${mark}</span><input name="model" value="${esc(s.model)}" ${required}></label><label><span class="field-title">연식${mark}</span><input name="modelYear" value="${esc(s.modelYear)}" inputmode="numeric" placeholder="예: 2022" ${required}></label></div><div class="form-row"><label><span class="field-title">총 주행거리</span><input name="mileage" value="${esc(s.mileage)}" placeholder="예: 18,634km"></label><label><span class="field-title">색상${mark}</span>${fresh?colorSelect(s.color):`<input name="color" value="${esc(normalizeVehicleColor(s.color))}" required>`}</label></div><label><span class="field-title">담당자${mark}</span><select name="manager" ${required}>${managerOptions(s.manager)}</select></label><label>옵션 <small>(선택)</small><input name="options" value="${esc(s.options)}" maxlength="500" placeholder="주요 옵션"></label><fieldset><legend>확인이 필요한 상태</legend><div class="status-list">${STATUS.map(x=>`<label><input type="checkbox" name="alerts" value="${x.id}" ${s.alerts.includes(x.id)?'checked':''}><span>${x.mark}</span>${x.label}</label>`).join('')}</div></fieldset><div class="modal-actions">${fresh?'<span></span>':s.isUnassigned?'<span></span>':'<div><button type="button" class="ghost danger" data-unassign>삭제</button></div>'}<button class="primary" data-save-vehicle ${state.saving?'disabled':''}>${state.saving?'저장 중…':fresh?'등록':'정보 저장'}</button></div></fieldset></form>`;}
async function openNewVehicle(){if(!requireBackend())return;try{const data=await api('heydealer');state.heydealerRecords=data.records||[];}catch{state.heydealerRecords=[];}state.spots=state.spots.filter(spot=>spot.id!=='draft');state.spots.push({id:'draft',plate:'',model:'',modelYear:'',mileage:'',color:'',options:'',manager:'',memo:'',alerts:[],zone:'차량 현황판',label:'신규 입고'});state.selected='draft';state.mode='detail';render();}
function bindHeydealerVehiclePicker(){const select=document.querySelector('[data-heydealer-vehicle]'),form=select?.form,fields=form?.querySelector('.checkin-fields');if(!select||!form||!fields)return;const sync=()=>{fields.disabled=!select.value;const record=state.heydealerRecords.find(item=>item.id===select.value),values=record?{plate:record.plate,model:record.model,modelYear:record.model_year,mileage:record.mileage,color:normalizeVehicleColor(record.color),manager:record.manager,options:record.options}:{plate:'',model:'',modelYear:'',mileage:'',color:'',manager:'',options:''};for(const [name,value] of Object.entries(values)){const field=form.elements.namedItem(name);if(field)field.value=value||'';}if(select.value==='manual')form.elements.namedItem('plate')?.focus();};select.addEventListener('change',sync);sync();}
function moveForm(s){const empty=state.spots.filter(x=>!used(x));return`<form id="move-form"><p class="move-car"><b>${esc(s.plate)}</b><span>${esc(s.model)} · ${esc(s.color)}</span></p><label>이동할 빈 자리<select name="destination" required><option value="">구역과 위치를 선택하세요</option>${zones.map(z=>{const list=empty.filter(x=>x.zoneId===z.id);return list.length?`<optgroup label="${z.name}">${list.map(x=>`<option value="${x.id}">${x.label}</option>`).join('')}</optgroup>`:''}).join('')}</select></label><div class="modal-actions"><button type="button" class="ghost" data-back>취소</button><button class="primary">이동 완료</button></div></form>`;}
