 const trigger=root.querySelector('.vehicle-list-trigger'),popover=root.querySelector('.vehicle-list-popover'),input=root.querySelector('input'),clear=root.querySelector('.vehicle-list-search button'),options=root.querySelector('.vehicle-list-options');
