function renderDashboard(){
 const selected=boardVehicles().find(s=>s.id===state.selected||s.vehicleId===state.selected),vehicles=boardVehicles().filter(vehicle=>!vehicle.isCheckedOut),groups=boardGroups(),categories=[['all','전체'],['대표님','대표님'],['황정웅대리','황대리'],['김지민대리','김대리'],['권용민주임','권주임']];
 app.innerHTML=`<header class="topbar"><a class="brand" href="/" aria-label="주차 위치 현황으로 이동"><img class="brand-mark" src="/favicon-32.png" alt=""><span><b>윤카</b></span></a><div class="header-actions">${sheetShortcut()}<nav class="board-nav"><a href="/">주차 위치 현황</a><button data-new>+ 신규 입차</button></nav></div></header><main class="board-page"><div class="demo-banner ${state.backend?'connected':''}" role="status"><b>${state.backend?'D1':'DEMO'}</b>${state.backend?'Cloudflare D1 운영 데이터에 연결됨':'읽기 전용 데모'}</div>${state.loading?'<div class="loading">차량을 불러오는 중입니다…</div>':''}${state.error?`<div class="toast error" role="alert">${esc(state.error)} <button data-dismiss>닫기</button></div>`:''}${state.notice?`<div class="toast">${esc(state.notice)}</div>`:''}<section class="board-hero"><div><p class="eyebrow">VEHICLE DASHBOARD</p><h1>차량 현황판</h1><p>담당자별 입고 차량을 확인하고 정보를 바로 수정하세요.</p></div><strong>${vehicles.length}<small>대</small></strong></section><nav class="manager-tabs" aria-label="담당자별 차량 보기">${categories.map(([id,label])=>id==='all'?`<span class="manager-all-tab"><button type="button" data-dashboard-sheet-sync disabled aria-label="스프레드시트 전체 동기화" title="전체 동기화"><img src="/sheets.png" alt=""></button><button data-manager-filter="${id}" class="${state.managerFilter===id?'active':''}"><span data-dashboard-sync-label>${label}</span></button><select data-dashboard-sheet-tab hidden aria-hidden="true" disabled><option value="">탭을 불러오는 중…</option></select></span>`:`<button data-manager-filter="${id}" class="${state.managerFilter===id?'active':''}">${label}</button>`).join('')}</nav><section class="board-tools">${searchControl('차량번호 · 차명 · 담당자 검색')}<form id="plate-assign-form" class="compact-assign"><label><span class="sr-only">차량번호 뒤 4자리</span><input name="last4" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="번호 뒤 4자리" required></label><button>주차 위치 지정</button></form></section><section class="manager-groups">${groups.length?groups.map(([manager,cars])=>`<article class="manager-group" data-manager="${esc(manager)}"><header><div class="manager-heading"><h2>${esc(manager)}</h2><b data-manager-count>${cars.length}대</b></div><div class="manager-header-actions"><div class="manager-status-filter" role="group" aria-label="${esc(manager)} 차량 상태 필터"><button type="button" data-manager-status="all" class="active" aria-pressed="true">전체</button><button type="button" data-manager-status="checked-out" aria-pressed="false">출고됨</button><button type="button" data-manager-status="active" aria-pressed="false">판매중</button></div><button type="button" class="manager-expand-toggle" data-manager-expand aria-expanded="false"><span aria-hidden="true">↓</span> 펼치기</button></div></header><div class="board-table"><div class="board-row board-labels"><button type="button" class="sequence-edit-button" data-sequence-edit aria-label="${esc(manager)} 순번 수정" title="순번 수정">✎</button><span>순번</span><span>차량번호</span><span>차명</span><span>연식</span><span>총 주행거리</span><span>색상</span><span>입고일</span><span>옵션</span>${BOARD_CHECKS.map(([,label])=>`<span class="board-check-label">${label}</span>`).join('')}</div>${cars.map((car,index)=>dashboardVehicleRow(car,index,cars.some(isPinnedBoardVehicle))).join('')}</div><nav class="board-pagination" aria-label="${esc(manager)} 차량 목록 페이지"></nav></article>`).join(''):'<div class="no-result"><strong>조건에 맞는 차량이 없습니다.</strong></div>'}</section></main>${selected?modal(selected):''}`;
 const dashboardSheetSelect=document.querySelector('[data-dashboard-sheet-tab]'),dashboardSyncButton=document.querySelector('[data-dashboard-sheet-sync]'),dashboardSyncLabel=document.querySelector('[data-dashboard-sync-label]');
 loadGoogleSheetTabs(dashboardSheetSelect,null,true).then(()=>{dashboardSyncButton.disabled=!dashboardSheetSelect.value;});
 const setDashboardSyncLabel=(value,dots=0)=>{dashboardSyncLabel.classList.toggle('is-sync-status',dots>0);if(dots>0)dashboardSyncLabel.innerHTML=`<span>동기화 중</span><i aria-hidden="true">${'.'.repeat(dots)}</i>`;else dashboardSyncLabel.textContent=value;};
 dashboardSyncButton.addEventListener('mouseenter',()=>{if(!dashboardSyncButton.classList.contains('is-syncing'))setDashboardSyncLabel('전체동기화');});
 dashboardSyncButton.addEventListener('mouseleave',()=>{if(!dashboardSyncButton.classList.contains('is-syncing'))setDashboardSyncLabel('전체');});
 dashboardSyncButton.addEventListener('focus',()=>{if(!dashboardSyncButton.classList.contains('is-syncing'))setDashboardSyncLabel('전체동기화');});
 dashboardSyncButton.addEventListener('blur',()=>{if(!dashboardSyncButton.classList.contains('is-syncing'))setDashboardSyncLabel('전체');});
 dashboardSyncButton.onclick=async event=>{event.stopPropagation();if(!dashboardSheetSelect.value)return;dashboardSyncButton.disabled=true;dashboardSyncButton.classList.add('is-syncing');let dots=1;setDashboardSyncLabel('',dots);const syncLabelTimer=setInterval(()=>{dots=dots%3+1;setDashboardSyncLabel('',dots);},450);try{const result=await api('google-sheets/sync-all',{method:'POST',body:JSON.stringify({tab:dashboardSheetSelect.value})});showPageToast(`전체 동기화 완료: 업데이트 ${result.updated}건, 추가 ${result.inserted}건, 실패 ${result.failed}건`,result.failed>0);}catch(error){showPageToast(error.message,true);}finally{clearInterval(syncLabelTimer);dashboardSyncButton.classList.remove('is-syncing');dashboardSyncButton.disabled=false;setDashboardSyncLabel(dashboardSyncButton.matches(':hover')||document.activeElement===dashboardSyncButton?'전체동기화':'전체');}};
 bindDashboard();
}
function driveField(name,label,type='text'){if(name==='notes')return`<div class="drive-customer-field"><label><span>${label} <small class="required-mark">(필수)</small></span><select name="notes" required><option value="">선택해 주세요</option>${CUSTOMER_TYPES.map(value=>`<option value="${value}">${value}</option>`).join('')}</select></label><label class="drive-file-button is-disabled" aria-label="법인 파일 첨부"><input type="file" name="corporateFile" accept="application/pdf,image/jpeg,image/png,image/webp,image/heic,image/heif" multiple disabled><span aria-hidden="true">📎</span><b>파일 업로드</b></label><small class="drive-file-name">법인을 선택하면 파일을 첨부할 수 있습니다.</small></div>`;const required=name!=='options';return`<label><span>${label}</span><input type="${type}" name="${name}" autocomplete="off" ${required?'required':''}></label>`;}
function fillDriveFields(form,data){Object.entries(data).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(field)field.value=value||'';});}
async function uploadHeydealerFile(recordId,file){const formData=new FormData();formData.append('file',file);const response=await fetch(`/api/heydealer/${recordId}/files`,{method:'POST',body:formData}),data=await response.json().catch(()=>({message:'파일 업로드 응답을 읽을 수 없습니다.'}));if(!response.ok)throw new Error(data.message||'파일을 업로드하지 못했습니다.');return data;}
const SHEET_TAB_STORAGE='hnauto-google-sheet-tab',DEFAULT_SHEET_TAB='수정용 시트';
function showPageToast(message,error=false){document.querySelector('.page-action-toast')?.remove();const toast=document.createElement('div');toast.className=`toast page-action-toast${error?' error':''}`;toast.setAttribute(error?'role':'aria-live',error?'alert':'polite');toast.textContent=message;document.body.append(toast);setTimeout(()=>toast.remove(),3200);}
async function loadGoogleSheetTabs(select,status,autoSelectFirst=false){try{const {tabs}=await api('google-sheets/tabs'),saved=localStorage.getItem(SHEET_TAB_STORAGE),savedTab=tabs.find(tab=>tab.title===saved),defaultTab=tabs.find(tab=>tab.title===DEFAULT_SHEET_TAB);select.innerHTML='<option value="">대상 탭을 선택해 주세요</option>'+tabs.map(tab=>`<option value="${esc(tab.title)}">${esc(tab.title)}</option>`).join('');select.disabled=false;if(defaultTab||savedTab||autoSelectFirst||tabs.length===1)select.value=(defaultTab||savedTab||tabs[0])?.title||'';if(select.value)localStorage.setItem(SHEET_TAB_STORAGE,select.value);}catch(error){select.innerHTML='<option value="">탭을 불러오지 못했습니다</option>';select.disabled=true;if(status){status.textContent=error.message;status.classList.add('is-error');}}}
function renderDrivePage(){
  app.innerHTML=`<header class="topbar"><a class="brand" href="/" aria-label="주차 위치 현황으로 이동"><img class="brand-mark" src="/favicon-32.png" alt=""><span><b>윤카</b></span></a><nav class="board-nav"><a href="/">주차 위치 현황</a><a href="/dashboard">차량 현황판</a></nav></header><main class="drive-page"><section class="drive-prompt-panel"><p class="drive-prompt-title">헤이딜러 거래 화면 전체를 아래 프롬프트에 붙여넣으면 거래 정보가 자동 입력됩니다.</p><form class="drive-vehicle-form" id="drive-vehicle-form"><div class="drive-field-grid">${driveField('manager','담당자')}${driveField('modelYear','연식')}${driveField('plate','차량번호')}${driveField('model','차종')}${driveField('color','색상')}${driveField('mileage','총 주행거리')}${driveField('options','옵션')}${driveField('notes','특이사항')}${driveField('price','차대금')}${driveField('account','입금계좌')}${driveField('origin','탁송출발지역')}${driveField('departureTime','출발시간')}</div></form><div class="drive-prompt-grid"><label for="drive-prompt"><span>헤이딜러 원문 붙여넣기 <b>(탁송인수 정보)</b></span><textarea id="drive-prompt" rows="8" maxlength="12000" placeholder="탁송인수 정보가 포함된 원문을 붙여넣으세요."></textarea></label><label for="drive-payment-prompt"><span>헤이딜러 원문 붙여넣기 <b>(차대금 입금)</b></span><textarea id="drive-payment-prompt" rows="8" maxlength="12000" placeholder="차대금 입금 정보가 포함된 원문을 붙여넣으세요."></textarea></label></div><p class="drive-parse-status" role="status">붙여넣으면 위 입력칸에 자동으로 반영됩니다.</p><select data-sheet-tab hidden aria-hidden="true" disabled><option value="">탭을 불러오는 중…</option></select><div class="drive-record-actions"><button type="button" data-drive-reset>초기화</button><button type="button" class="primary" data-drive-save>저장</button></div></section></main>`;
  const form=document.querySelector('#drive-vehicle-form'),prompts=[document.querySelector('#drive-prompt'),document.querySelector('#drive-payment-prompt')],status=document.querySelector('.drive-parse-status'),sheetSelect=document.querySelector('[data-sheet-tab]'),customerSelect=form.elements.namedItem('notes'),fileInput=form.elements.namedItem('corporateFile'),fileButton=form.querySelector('.drive-file-button'),fileName=form.querySelector('.drive-file-name'),empty={manager:'',modelYear:'',plate:'',model:'',color:'',mileage:'',options:'',notes:'',price:'',account:'',origin:'',departureTime:''};let savedRecordId='',fileUploaded=false;
  const syncFileInput=()=>{const enabled=isCorporateCustomer(customerSelect.value),files=[...fileInput.files];fileInput.disabled=!enabled;fileButton.classList.toggle('is-disabled',!enabled);if(!enabled){fileInput.value='';fileName.textContent='개인 거래는 파일 첨부가 필요하지 않습니다.';}else fileName.textContent=files.length===1?files[0].name:files.length?`${files.length}개 파일 선택됨`:'클립을 눌러 법인 서류를 선택하세요.';};
  const reset=()=>{savedRecordId='';fileUploaded=false;fillDriveFields(form,empty);prompts.forEach(prompt=>{prompt.value='';});syncFileInput();status.textContent='붙여넣으면 위 입력칸에 자동으로 반영됩니다.';};
  const mergeParsed=parsed=>{Object.entries(parsed).forEach(([name,value])=>{if(name==='notes')return;const field=form.elements.namedItem(name);if(field&&value)field.value=value;});syncFileInput();};
  fillDriveFields(form,empty);
  loadGoogleSheetTabs(sheetSelect,status,true);
  customerSelect.addEventListener('change',syncFileInput);fileInput.addEventListener('change',syncFileInput);syncFileInput();
  prompts.forEach(prompt=>prompt.addEventListener('input',()=>{if(!prompt.value.trim())return;const parsed=parseHeydealerText(prompt.value);mergeParsed(parsed);status.textContent=parsed.plate?`${parsed.plate} 차량 정보를 자동 입력했습니다.`:'인식된 정보를 기존 입력값에 반영했습니다.';}));
  document.querySelector('[data-drive-reset]').onclick=reset;
  let savingTimer;const stopSaving=(button,label)=>{clearInterval(savingTimer);savingTimer=undefined;button.textContent=label;};const startSaving=button=>{let dotCount=1;const draw=()=>{button.innerHTML=`<span class="drive-saving-label">저장 중<span class="drive-saving-dots" aria-hidden="true">${'.'.repeat(dotCount)}</span></span>`;};button.disabled=true;draw();savingTimer=setInterval(()=>{dotCount=dotCount%3+1;draw();},450);};
  document.querySelector('[data-drive-save]').onclick=async event=>{const button=event.currentTarget,formData=new FormData(form),corporateFiles=formData.getAll('corporateFile').filter(file=>file?.size);formData.delete('corporateFile');const values=Object.fromEntries(formData),requiredNames=['manager','modelYear','plate','model','color','mileage','notes','price','account','origin','departureTime'],missing=requiredNames.find(name=>!String(values[name]||'').trim());if(missing||!CUSTOMER_TYPES.includes(values.notes)){status.textContent='필수사항을 입력하세요.';status.classList.add('is-error');form.elements.namedItem(missing||'notes')?.focus();return;}if(!sheetSelect.value){status.textContent='대상 탭을 선택해 주세요.';status.classList.add('is-error');sheetSelect.focus();return;}status.classList.remove('is-error');startSaving(button);status.textContent='저장 중';try{const rawPickupText=prompts[0].value,rawPaymentText=prompts[1].value;if(!savedRecordId){const result=await api('heydealer',{method:'POST',body:JSON.stringify({...values,customerType:values.notes,rawPickupText,rawPaymentText})});savedRecordId=result.id;}if(isCorporateCustomer(values.notes)&&corporateFiles.length&&!fileUploaded){for(const file of corporateFiles)await uploadHeydealerFile(savedRecordId,file);fileUploaded=true;}const result=await api('google-sheets/sync-vehicle',{method:'POST',body:JSON.stringify({recordId:savedRecordId,tab:sheetSelect.value,notifyCalendar:true})}),message=result.action==='updated'?`차량 정보를 ${sheetSelect.value} 시트에 업데이트했습니다.`:`차량을 ${sheetSelect.value} 시트에 추가했습니다.`;stopSaving(button,'저장 완료');status.textContent=message;showPageToast(message);setTimeout(()=>{location.href='/drive/heydealer';},1400);}catch(error){stopSaving(button,'저장');status.textContent=error.message;status.classList.add('is-error');showPageToast(error.message,true);button.disabled=false;}};
  addExternalTools();bindInternalViewNavigation();configureFooter();addFooterControls();syncMobileControlScale();
}
function heydealerEditForm(record){const input=(name,label,value,type='text',optional=false)=>`<label><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${optional?'':'required'}></label>`,corporate=isCorporateCustomer(record.customer_type);return`<form class="heydealer-edit-form" data-heydealer-edit-form="${esc(record.id)}"><div class="drive-field-grid">${input('manager','담당자',record.manager)}${input('recordDate','날짜',record.record_date,'date')}${input('plate','차량번호',record.plate)}${input('model','차종',record.model)}${input('modelYear','연식',record.model_year)}${input('color','색상',record.color)}${input('mileage','총 주행거리',record.mileage)}${input('options','옵션',record.options,'text',true)}<div class="heydealer-edit-customer"><label><span>특이사항</span><select name="customerType" required>${CUSTOMER_TYPES.map(value=>`<option value="${value}" ${record.customer_type===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="heydealer-edit-file-button ${corporate?'':'is-disabled'}" aria-label="법인 파일 첨부" title="법인 파일 업로드"><input type="file" name="corporateFile" accept="application/pdf,image/jpeg,image/png,image/webp,image/heic,image/heif" multiple ${corporate?'':'disabled'}><span aria-hidden="true">📎</span></label><small data-edit-file-name>${corporate?'클립을 눌러 법인 서류를 선택하세요.':'법인을 선택하면 파일을 첨부할 수 있습니다.'}</small></div>${input('price','차대금',record.price)}${input('account','입금계좌',record.account)}${input('origin','탁송출발지역',record.origin)}${input('departureTime','출발시간',record.departure_time)}</div><div class="heydealer-edit-actions"><button type="button" data-heydealer-edit-cancel>취소</button><button type="submit" class="primary">저장</button></div></form>`;}
function heydealerRecord(record,editing=false){const fields=[['담당자',record.manager],['연식',record.model_year],['색상',record.color],['총 주행거리',record.mileage],['옵션',record.options],['특이사항',record.customer_type],['차대금',record.price],['입금계좌',record.account],['탁송출발지역',record.origin],['출발시간',record.departure_time]],rawText=[record.raw_pickup_text,record.raw_payment_text].filter(Boolean).join('\n\n'),files=record.files||[],corporate=isCorporateCustomer(record.customer_type);return`<article class="heydealer-record${editing?' is-editing':''}" data-heydealer-record="${esc(record.id)}"><header><div><div class="heydealer-record-title"><strong>${esc(record.plate)||'차량번호 미입력'}</strong>${corporate?`<span class="corporate-label">${customerBadge(record.customer_type)}</span><button type="button" class="heydealer-download" data-heydealer-files="${esc(record.id)}">다운로드</button>`:''}</div><h2>${esc(record.model)||'차종 미입력'}</h2></div><div class="heydealer-record-meta"><time datetime="${esc(record.record_date)}">${esc(record.record_date)}</time><div class="heydealer-record-buttons"><button type="button" class="heydealer-edit" data-heydealer-edit="${esc(record.id)}" aria-label="${esc(record.plate)} 수정" title="수정">✎</button><button type="button" class="heydealer-delete" data-heydealer-delete="${esc(record.id)}" aria-label="${esc(record.plate)} 삭제" title="삭제">🗑</button></div></div></header><details class="heydealer-record-details" ${editing?'open':''}><summary>${editing?'접기':'펼치기'}</summary>${editing?heydealerEditForm(record):`<dl>${fields.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)||'-'}</dd></div>`).join('')}</dl>${files.length?`<div class="heydealer-files"><strong>첨부파일</strong>${files.map(file=>`<a href="/api/heydealer/${esc(record.id)}/files/${esc(file.id)}" download>📎 ${esc(file.filename)}</a>`).join('')}</div>`:''}${rawText?`<div class="heydealer-raw"><strong>붙여넣은 원문</strong><pre>${esc(rawText)}</pre></div>`:''}`}</details></article>`;}
async function openHeydealerFiles(record){document.querySelector('.heydealer-files-backdrop')?.remove();let files=record.files||[];try{const latest=(await api('heydealer')).records.find(item=>item.id===record.id);if(latest){files=latest.files||[];record.files=files;}}catch(error){showPageToast(error.message,true);}const backdrop=document.createElement('div');backdrop.className='modal-backdrop heydealer-files-backdrop';backdrop.innerHTML=`<section class="modal heydealer-files-modal" role="dialog" aria-modal="true" aria-labelledby="heydealer-files-title"><button class="modal-close" type="button" data-files-close aria-label="첨부파일 닫기">×</button>${files.length?'<button class="heydealer-download-all" type="button" data-files-download-all>전체다운로드</button>':''}<h2 id="heydealer-files-title">${esc(record.plate)} 첨부파일</h2>${files.length?`<ul>${files.map(file=>`<li><span title="${esc(file.filename)}">${esc(file.filename)}</span><a href="/api/heydealer/${esc(record.id)}/files/${esc(file.id)}" download>다운로드</a></li>`).join('')}</ul>`:'<p class="heydealer-files-empty">업로드된 파일이 없습니다.</p>'}</section>`;document.body.append(backdrop);const close=()=>backdrop.remove();backdrop.querySelector('[data-files-close]').onclick=close;backdrop.querySelector('[data-files-download-all]')?.addEventListener('click',()=>{backdrop.querySelectorAll('li a[download]').forEach(link=>link.click());});backdrop.addEventListener('click',event=>{if(event.target===backdrop)close();});backdrop.addEventListener('keydown',event=>{if(event.key==='Escape')close();});backdrop.querySelector('[data-files-close]').focus();}
function heydealerPagination(current,total){if(total<=1)return'';const pages=[];for(let page=1;page<=total;page++){if(page===1||page===total||Math.abs(page-current)<=1)pages.push(`<button type="button" data-heydealer-page="${page}" class="${page===current?'active':''}" aria-current="${page===current?'page':'false'}">${page}</button>`);else if(pages.at(-1)!=='<span>…</span>')pages.push('<span>…</span>');}return`<button type="button" data-heydealer-page="1" ${current===1?'disabled':''}>맨처음</button><button type="button" data-heydealer-page="${current-1}" ${current===1?'disabled':''} aria-label="이전 페이지">&lt;</button>${pages.join('')}<button type="button" data-heydealer-page="${current+1}" ${current===total?'disabled':''} aria-label="다음 페이지">&gt;</button><button type="button" data-heydealer-page="${total}" ${current===total?'disabled':''}>맨끝</button>`;}
