function openEncarApp(event){if(!/Android|iPhone|iPad|iPod/i.test(navigator.userAgent))return;event.preventDefault();const webUrl=event.currentTarget.href;if(/Android/i.test(navigator.userAgent)){location.href=`intent://www.encar.com/sl/sl_index.do?method=guaranteeSaleInfo#Intent;scheme=https;package=com.encar.encarMobileApp;S.browser_fallback_url=${encodeURIComponent(webUrl)};end`;return;}location.href=webUrl;}
function todayCalendarLabel(now=new Date()){const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}),parts=Object.fromEntries(formatter.formatToParts(now).map(part=>[part.type,part.value])),weekday=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',weekday:'short'}).format(now);return`${parts.year}-${parts.month}-${parts.day} (${weekday})`;}
const calendarMonthValue=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;
